async function loadGantt(projectId = '') {
  const query = projectId ? `?project_id=${encodeURIComponent(projectId)}` : '';
  const data = await api(`/projects/gantt${query}`);
  const definition = domainDefinitions.projects;
  const project = data.project;
  const dateValue = value => value ? new Date(`${String(value).slice(0, 10)}T00:00:00Z`) : null;
  const dayDiff = (from, to) => Math.round((to - from) / 86400000);
  const formatDate = value => value ? String(value).slice(0, 10) : '—';
  if (!project) {
    $('#workspace-content').innerHTML = `${domainNav(definition, 'gantt')}<section class="hero"><div><p class="eyebrow">MÓDULO PROYECTOS / GANTTS</p><h2>Gantt por proyecto</h2><p>Registra proyectos para visualizar su planificación temporal.</p></div></section><div class="empty-state">Aún no hay proyectos para mostrar.</div>`;
    document.querySelectorAll('[data-domain-section]').forEach(button => button.addEventListener('click', () => loadDomain('projects', button.dataset.domainSection)));
    return;
  }
  const projectStart = dateValue(project.start_date) || new Date();
  const projectEnd = dateValue(project.end_date || project.planned_end_date) || new Date(projectStart.getTime() + 86400000);
  const taskDates = data.tasks.flatMap(task => [dateValue(task.planned_start), dateValue(task.planned_end)]).filter(Boolean);
  const start = new Date(Math.min(projectStart.getTime(), ...taskDates.map(item => item.getTime())));
  const end = new Date(Math.max(projectEnd.getTime(), ...taskDates.map(item => item.getTime())));
  const span = Math.max(1, dayDiff(start, end) + 1);
  const monthLabels = [];
  const cursor = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth(), 1));
  while (cursor <= end) { monthLabels.push(cursor.toLocaleDateString('es-PE', { month: 'short', year: 'numeric', timeZone: 'UTC' })); cursor.setUTCMonth(cursor.getUTCMonth() + 1); }
  const statusLabels = { planned: 'Planificada', in_progress: 'En ejecución', blocked: 'Bloqueada', completed: 'Completada', cancelled: 'Cancelada' };
  const rows = data.tasks.map(task => { const taskStart = dateValue(task.planned_start) || projectStart; const taskEnd = dateValue(task.planned_end) || taskStart; const left = Math.max(0, dayDiff(start, taskStart) / span * 100); const width = Math.max(1.5, (dayDiff(taskStart, taskEnd) + 1) / span * 100); const actual = task.actual_start || task.actual_end ? ` · Real: ${formatDate(task.actual_start)} → ${formatDate(task.actual_end)}` : ''; return `<div class="gantt-row"><div class="gantt-label"><strong>${htmlEscape(task.task_code)}</strong><span>${htmlEscape(task.name)}</span><small>${task.is_dead_time ? 'Tiempo muerto' : 'Productiva'} · ${statusLabels[task.status] || task.status}</small></div><div class="gantt-track"><div class="gantt-bar ${task.is_dead_time ? 'dead-time' : ''} ${task.status === 'completed' ? 'completed' : ''}" style="left:${left}%;width:${width}%" title="${htmlEscape(task.name)}${actual}">${htmlEscape(task.task_code)}</div></div></div>`; }).join('');
  $('#page-title').textContent = definition.title;
  $('#workspace-content').innerHTML = `${domainNav(definition, 'gantt')}<section class="hero"><div><p class="eyebrow">MÓDULO PROYECTOS / GANTTS</p><h2>Gantt por proyecto</h2><p>Visualiza planificación, documentación como tiempo muerto y fechas reales de ejecución.</p></div><div class="gantt-project-summary"><strong>${htmlEscape(project.project_code)}</strong><span>${htmlEscape(formatDate(project.start_date))} → ${htmlEscape(formatDate(project.end_date || project.planned_end_date))}</span></div></section><section class="module-card gantt-card"><div class="gantt-toolbar"><label>Proyecto<select id="gantt-project-select">${data.projects.map(item => `<option value="${item.id}" ${String(item.id) === String(project.id) ? 'selected' : ''}>${htmlEscape(item.project_code)} · ${htmlEscape(item.name)}</option>`).join('')}</select></label><div class="gantt-legend"><span><i class="legend-dot productive"></i>Productiva</span><span><i class="legend-dot dead"></i>Tiempo muerto</span><span><i class="legend-dot complete"></i>Completada</span></div></div><div class="gantt-meta"><span>Inicio: <strong>${formatDate(project.start_date)}</strong></span><span>Fecha final comprometida: <strong>${formatDate(project.planned_end_date)}</strong></span><span>Fin real: <strong>${formatDate(project.end_date)}</strong></span><span>${data.tasks.length} tareas</span></div><div class="gantt-scroll"><div class="gantt-months"><div></div><div class="gantt-month-track">${monthLabels.map(label => `<span>${htmlEscape(label)}</span>`).join('')}</div></div>${rows || '<div class="empty-state">Este proyecto aún no tiene tareas.</div>'}</div></section>`;
  $('#gantt-project-select').addEventListener('change', event => loadGantt(event.target.value));
  document.querySelectorAll('[data-domain-section]').forEach(button => button.addEventListener('click', () => loadDomain('projects', button.dataset.domainSection)));
}

async function loadProjects() {
  const [{ projects }, { orders }] = await Promise.all([api('/projects/projects'), api('/projects/service-orders')]);
  const definition = domainDefinitions.projects;
  const orderOptions = orders.map(order => `<option value="${order.id}">${htmlEscape(order.order_code)} · ${htmlEscape(order.description || 'Orden de servicio')}</option>`).join('');
  const statusLabels = { planned: 'Planificado', active: 'Activo', completed: 'Completado', cancelled: 'Cancelado' };
  const projectRows = projects.length ? `<div class="directory-table-wrap"><table class="directory-table"><thead><tr><th>ID proyecto</th><th>Nombre</th><th>Orden</th><th>Inicio</th><th>Fecha final comprometida</th><th>Fin real</th><th>Días restantes</th><th>Estado</th><th>Documentación</th><th>Acciones</th></tr></thead><tbody>${projects.map(project => `<tr><td><strong>${htmlEscape(project.project_code)}</strong></td><td>${htmlEscape(project.name)}</td><td>${htmlEscape(project.order_code)}</td><td>${htmlEscape(String(project.start_date || '—'))}</td><td>${htmlEscape(String(project.planned_end_date || 'Sin definir'))}</td><td>${htmlEscape(String(project.end_date || '—'))}</td><td>${project.end_date ? 'Cerrado' : project.days_remaining === null ? '—' : Number(project.days_remaining) < 0 ? `Vencido ${Math.abs(Number(project.days_remaining))} d` : `${project.days_remaining} d`}</td><td>${statusLabels[project.status] || project.status}</td><td>${project.documentation_count || 0}/7 áreas · ${project.documents_uploaded || 0} PDF</td><td><div class="table-actions"><button class="link-button" type="button" data-edit-project="${project.id}">Editar</button><button class="link-button" type="button" data-project-documentation="${project.id}">Documentación</button></div></td></tr>`).join('')}</tbody></table></div>` : '';
  $('#workspace-content').innerHTML = `${domainNav(definition, 'projects')}<section class="hero"><div><p class="eyebrow">MÓDULO PROYECTOS / PROYECTOS</p><h2>Proyectos</h2><p>Directorio de proyectos asociados a órdenes de servicio y documentación por área.</p></div><button class="primary customer-new-button" id="new-project" type="button">+ Nuevo proyecto</button></section><section class="module-card customer-directory"><div class="section-heading"><div><h3>Directorio</h3><p class="muted">${projects.length} proyecto${projects.length === 1 ? '' : 's'} registrado${projects.length === 1 ? '' : 's'}.</p></div></div><div class="customer-list">${projectRows || '<div class="empty-state">Aún no hay proyectos. Registra el primero con el botón “Nuevo proyecto”.</div>'}</div></section><div class="modal-backdrop" id="project-modal" hidden><section class="customer-modal project-modal" role="dialog" aria-modal="true" aria-labelledby="project-form-title"><div class="customer-modal-header"><div><p class="eyebrow">PORTAFOLIO</p><h3 id="project-form-title">Nuevo proyecto</h3><p class="muted">El inicio se toma de la recepción final de la Orden de Servicio.</p></div><button class="modal-close" id="project-cancel" type="button" aria-label="Cerrar">×</button></div><form id="project-form" class="customer-form"><input type="hidden" name="project_id"><label>Orden de servicio asociada *<select name="service_order_id" required><option value="">Selecciona una orden</option>${orderOptions}</select></label><div class="customer-grid"><label>ID de proyecto *<input name="project_code" required placeholder="PRJ-0001"></label><label>Nombre del proyecto *<input name="name" required placeholder="Proyecto de estructura"></label><label>Estado<select name="status"><option value="planned">Planificado</option><option value="active">Activo</option><option value="completed">Completado</option><option value="cancelled">Cancelado</option></select></label><label>Fecha de término<input name="end_date" type="date"><small class="muted">Se usa al marcar el proyecto como completado.</small></label></div><label>Descripción<textarea name="description" placeholder="Alcance general del proyecto"></textarea></label><label>Observaciones<textarea name="observations" placeholder="Notas generales"></textarea></label><div class="company-form-footer"><button class="primary" type="submit">Guardar proyecto</button><button class="link-button" id="project-reset" type="button" hidden>Cancelar edición</button></div></form></section></div><div class="modal-backdrop" id="documentation-modal" hidden><section class="customer-modal documentation-modal" role="dialog" aria-modal="true" aria-labelledby="documentation-title"><div class="customer-modal-header"><div><p class="eyebrow">PROYECTO / DOCUMENTACIÓN</p><h3 id="documentation-title">Documentación por áreas</h3><p class="muted">Cada área puede registrar su responsable, estado, fechas y PDF sustentatorio.</p></div><button class="modal-close" id="documentation-cancel" type="button" aria-label="Cerrar">×</button></div><div id="documentation-list" class="documentation-list"></div></section></div>`;
  const projectForm = $('#project-form'); const projectModal = $('#project-modal'); const documentationModal = $('#documentation-modal');
  const resetProjectForm = () => { projectForm.reset(); projectForm.elements.project_id.value = ''; projectForm.elements.status.value = 'planned'; $('#project-form-title').textContent = 'Nuevo proyecto'; $('#project-reset').hidden = true; };
  const closeProjectModal = () => { projectModal.hidden = true; document.body.classList.remove('modal-open'); };
  const openProjectModal = () => { projectModal.hidden = false; document.body.classList.add('modal-open'); projectForm.elements.service_order_id.focus(); };
  $('#new-project').addEventListener('click', () => { resetProjectForm(); openProjectModal(); });
  $('#project-cancel').addEventListener('click', () => { closeProjectModal(); resetProjectForm(); });
  $('#project-reset').addEventListener('click', () => { closeProjectModal(); resetProjectForm(); });
  projectModal.addEventListener('click', event => { if (event.target === projectModal) { closeProjectModal(); resetProjectForm(); } });
  projectForm.addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(projectForm)); const payload = { project_code: values.project_code, name: values.name, service_order_id: Number(values.service_order_id), end_date: values.end_date || null, description: values.description || null, observations: values.observations || null, status: values.status }; const projectId = values.project_id; try { await api(projectId ? `/projects/projects/${projectId}` : '/projects/projects', { method: projectId ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); closeProjectModal(); toast(projectId ? 'Proyecto actualizado' : 'Proyecto registrado'); loadProjects(); } catch (error) { toast(error.message); } });
  document.querySelectorAll('[data-edit-project]').forEach(button => button.addEventListener('click', () => { const project = projects.find(item => String(item.id) === button.dataset.editProject); if (!project) return; projectForm.elements.project_id.value = project.id; projectForm.elements.project_code.value = project.project_code; projectForm.elements.name.value = project.name; projectForm.elements.service_order_id.value = project.service_order_id; projectForm.elements.end_date.value = project.end_date || ''; projectForm.elements.description.value = project.description || ''; projectForm.elements.observations.value = project.observations || ''; projectForm.elements.status.value = project.status; $('#project-form-title').textContent = 'Editar proyecto'; $('#project-reset').hidden = false; openProjectModal(); }));
  const renderDocumentation = (project, areas) => { $('#documentation-title').textContent = `Documentación · ${project.project_code}`; $('#documentation-list').innerHTML = areas.map(area => `<form class="area-document-card" data-area-form="${area.area_key}"><div class="area-document-heading"><div><span class="pill ${area.status === 'approved' ? 'active' : area.status === 'rejected' ? 'planned' : 'active'}">${htmlEscape(area.area_name)}</span><h4>${area.file_id ? 'Documentación registrada' : 'Pendiente de documentación'}</h4></div><span class="muted">${area.file_id ? htmlEscape(area.file_name) : 'Sin PDF'}</span></div><div class="customer-grid"><label>Contacto *<input name="contact_name" value="${htmlEscape(area.contact_name || '')}" required placeholder="Responsable del área"></label><label>Fecha de ingreso *<input name="entered_at" type="date" value="${htmlEscape(area.entered_at || '')}" required></label><label>Estado<select name="status"><option value="pending" ${area.status === 'pending' ? 'selected' : ''}>Pendiente</option><option value="in_review" ${area.status === 'in_review' ? 'selected' : ''}>En revisión</option><option value="approved" ${area.status === 'approved' ? 'selected' : ''}>Aprobado</option><option value="rejected" ${area.status === 'rejected' ? 'selected' : ''}>Rechazado</option></select></label><label>Fecha de aprobación<input name="approved_at" type="date" value="${htmlEscape(area.approved_at || '')}"></label></div><label>PDF sustentatorio<input name="file" type="file" accept="application/pdf,.pdf"><small class="muted">Solo PDF, máximo 25 MB.</small></label><label>Observaciones<textarea name="observations" placeholder="Observaciones del área">${htmlEscape(area.observations || '')}</textarea></label><div class="area-document-footer"><span>${area.file_id ? `<a class="link-button" href="/ind-api/projects/projects/${project.id}/documentation/${area.area_key}/file" target="_blank">Descargar PDF</a>` : 'Puedes cargar el PDF cuando esté disponible.'}</span><button class="primary" type="submit">Guardar ${htmlEscape(area.area_name)}</button></div></form>`).join(''); document.querySelectorAll('[data-area-form]').forEach(form => form.addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(form)); const payload = { contact_name: values.contact_name, observations: values.observations || null, entered_at: values.entered_at, status: values.status, approved_at: values.approved_at || null }; const body = new FormData(); body.append('payload_json', JSON.stringify(payload)); if (form.elements.file.files[0]) body.append('file', form.elements.file.files[0]); try { await api(`/projects/projects/${project.id}/documentation/${form.dataset.areaForm}`, { method: 'PUT', body }); toast(`${form.dataset.areaForm} guardada`); const response = await api(`/projects/projects/${project.id}/documentation`); renderDocumentation(project, response.areas); } catch (error) { toast(error.message); } })); };
  const openDocumentation = async projectId => { const project = projects.find(item => String(item.id) === String(projectId)); if (!project) return; try { const response = await api(`/projects/projects/${project.id}/documentation`); renderDocumentation(project, response.areas); documentationModal.hidden = false; document.body.classList.add('modal-open'); } catch (error) { toast(error.message); } };
  document.querySelectorAll('[data-project-documentation]').forEach(button => button.addEventListener('click', () => openDocumentation(button.dataset.projectDocumentation)));
  $('#documentation-cancel').addEventListener('click', () => { documentationModal.hidden = true; document.body.classList.remove('modal-open'); });
  documentationModal.addEventListener('click', event => { if (event.target === documentationModal) { documentationModal.hidden = true; document.body.classList.remove('modal-open'); } });
  resetProjectForm();
  document.querySelectorAll('[data-domain-section]').forEach(button => button.addEventListener('click', () => loadDomain('projects', button.dataset.domainSection)));
}

